import{_ as l,o as i,c as e,a0 as r}from"./chunks/framework.jwovEGr5.js";const c=JSON.parse('{"title":"电脑装机全套知识","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"电脑知识/电脑装机.md","filePath":"电脑知识/电脑装机.md"}'),o={name:"电脑知识/电脑装机.md"};function t(h,a,n,d,s,p){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="电脑装机全套知识" tabindex="-1">电脑装机全套知识 <a class="header-anchor" href="#电脑装机全套知识" aria-label="Permalink to &quot;电脑装机全套知识&quot;">​</a></h1><p>零基础全覆盖，分为：装机硬件选型、组装实操、装系统、系统优化避坑、新机设置</p><p><strong>来源：豆包ai</strong></p><p>仅供学习参考！！！</p><h2 id="一、核心硬件认知" tabindex="-1">一、核心硬件认知 <a class="header-anchor" href="#一、核心硬件认知" aria-label="Permalink to &quot;一、核心硬件认知&quot;">​</a></h2><p>决定性能</p><p>一台电脑8大件，各司其职</p><h3 id="_1-cpu" tabindex="-1">1.CPU <a class="header-anchor" href="#_1-cpu" aria-label="Permalink to &quot;1.CPU&quot;">​</a></h3><p>中央处理器，电脑大脑</p><p>两大品牌：Intel、AMD</p><ul><li>定位：决定多开、剪辑、办公、游戏帧数下限</li><li>后缀说明（快速区分） Intel：带K=可超频；F=无核显（必须插独立显卡才能开机）；HX=笔记本高性能 AMD：X=加强版；G=带核显（不用独显亮机）</li><li>两种使用场景 ①有独立显卡：直接选带F无核显版本省钱 ②无独显过渡/办公：选带核显CPU，不用买显卡就能点亮电脑</li></ul><h3 id="_2-主板" tabindex="-1">2.主板 <a class="header-anchor" href="#_2-主板" aria-label="Permalink to &quot;2.主板&quot;">​</a></h3><p>硬件桥梁，所有配件插在主板上</p><ul><li>芯片等级：入门→中端→高端，只决定超频、接口数量、扩展性，不直接提升性能</li><li>硬性匹配规则：<strong>CPU针脚必须和主板匹配，不能混用</strong></li><li>刚需接口：M.2固态硬盘插槽、USB3.2、HDMI/DP视频口、2.5G网口</li></ul><h3 id="_3-显卡" tabindex="-1">3.显卡 <a class="header-anchor" href="#_3-显卡" aria-label="Permalink to &quot;3.显卡&quot;">​</a></h3><p>GPU，游戏、渲染、AI绘图核心</p><ul><li>N卡（NVIDIA）：游戏优化好、支持CUDA、AI绘图、视频剪辑加速（RTX4060、4070、5070）</li><li>A卡（AMD）：同价位显存更大，性价比高，直播、渲染划算</li><li>避坑：整机低价“高端独显”大概率是翻新矿卡，新手尽量买全新盒装</li></ul><h3 id="_4-内存条" tabindex="-1">4.内存条 <a class="header-anchor" href="#_4-内存条" aria-label="Permalink to &quot;4.内存条&quot;">​</a></h3><p>临时运行内存</p><ul><li>规格：DDR4（老平台）、DDR5（新款平台）</li><li>容量刚需：办公8G够用；游戏/多开16G双通道；剪辑32G起步</li><li>双通道：两根同规格内存，性能比单根强15%-25%</li></ul><h3 id="_5-固态硬盘" tabindex="-1">5.固态硬盘 <a class="header-anchor" href="#_5-固态硬盘" aria-label="Permalink to &quot;5.固态硬盘&quot;">​</a></h3><p>系统、游戏、软件存放，决定开机、加载速度</p><p>两类：</p><ol><li>M.2 NVMe（长条固态，主板直插，速度最快，系统盘首选）</li><li>SATA固态（2.5寸小硬盘，老电脑升级扩容用）</li></ol><p>⚠️不要用机械硬盘装系统，开机1分钟起步，体验极差</p><h3 id="_6-机械硬盘hdd" tabindex="-1">6.机械硬盘HDD <a class="header-anchor" href="#_6-机械硬盘hdd" aria-label="Permalink to &quot;6.机械硬盘HDD&quot;">​</a></h3><p>仓库盘，只存视频、文件、资料</p><p>优点：超大容量便宜，缺点速度慢，不装系统和游戏</p><h3 id="_7-电源" tabindex="-1">7.电源 <a class="header-anchor" href="#_7-电源" aria-label="Permalink to &quot;7.电源&quot;">​</a></h3><p>整机供电，重中之重，不能缩水</p><ul><li>额定功率计算：整机功耗总和+150W余量</li><li>等级：铜牌、银牌、金牌、白金牌（转换效率越高越省电）</li><li>致命坑：杂牌虚标电源，容易烧坏CPU、显卡、主板，直接买一线品牌</li></ul><h3 id="_8-机箱-散热器" tabindex="-1">8.机箱+散热器 <a class="header-anchor" href="#_8-机箱-散热器" aria-label="Permalink to &quot;8.机箱+散热器&quot;">​</a></h3><ul><li>CPU散热器：风冷（百元内够用）、水冷（颜值+高性能超频使用）</li><li>机箱：注意显卡限长、散热器限高、风道（前进后出上出风，散热更稳）</li></ul><h2 id="二、装机硬件搭配黄金公式" tabindex="-1">二、装机硬件搭配黄金公式 <a class="header-anchor" href="#二、装机硬件搭配黄金公式" aria-label="Permalink to &quot;二、装机硬件搭配黄金公式&quot;">​</a></h2><ol><li>办公网课主机（无独显） 带核显CPU+入门主板+16G内存+512G NVMe固态+400W电源</li><li>主流游戏主机（1080P高帧网游、3A） 中端CPU+B系列主板+16G双通道+1TB固态+中端显卡+550W金牌电源</li><li>4K游戏/剪辑生产力 高端CPU+Z/X系列超频主板+32G内存+2TB高速固态+高端显卡+750W以上全模组电源</li></ol><h2 id="三、手动装机实操顺序" tabindex="-1">三、手动装机实操顺序 <a class="header-anchor" href="#三、手动装机实操顺序" aria-label="Permalink to &quot;三、手动装机实操顺序&quot;">​</a></h2><p>防静电是第一步</p><ol><li>释放静电：手摸一下金属暖气片/机箱铁皮，消除静电，防止击穿主板芯片</li><li>主板上预装：CPU→CPU散热器→内存条→M.2固态硬盘</li><li>把装好配件的主板整体放入机箱，固定铜柱螺丝</li><li>安装电源、机箱风扇接线</li><li>装入独立显卡、机械硬盘</li><li>插线：主板24pin供电、CPU 4/8pin供电、显卡6/8pin供电、机箱跳线（开机、重启、USB、音频）</li><li>接上显示器、电源线，开机测试点亮</li></ol><h3 id="跳线小知识点-最难" tabindex="-1">跳线小知识点（最难） <a class="header-anchor" href="#跳线小知识点-最难" aria-label="Permalink to &quot;跳线小知识点（最难）&quot;">​</a></h3><p>机箱前置跳线在主板右下角，有印刷标识：</p><p>POWER SW=开机键、RESET SW=重启键、HD LED=硬盘指示灯、POWER LED=电源灯</p><p>正负极除了LED灯需要区分，开关机针脚不分正负随便插。</p><h2 id="四、装系统" tabindex="-1">四、装系统 <a class="header-anchor" href="#四、装系统" aria-label="Permalink to &quot;四、装系统&quot;">​</a></h2><p>Windows安装，最常用</p><h3 id="_1-准备工具" tabindex="-1">1.准备工具 <a class="header-anchor" href="#_1-准备工具" aria-label="Permalink to &quot;1.准备工具&quot;">​</a></h3><p>8G以上U盘，用微软官方工具<strong>Media Creation Tool</strong>制作原版Windows10/11启动盘</p><p>拒绝：电脑城GHOST镜像（捆绑病毒、广告、后门）</p><h3 id="_2-bios启动u盘" tabindex="-1">2.BIOS启动U盘 <a class="header-anchor" href="#_2-bios启动u盘" aria-label="Permalink to &quot;2.BIOS启动U盘&quot;">​</a></h3><p>开机按快捷键（主板品牌不同：Del、F2、F11、F12），选择U盘启动</p><h3 id="_3-系统安装步骤" tabindex="-1">3.系统安装步骤 <a class="header-anchor" href="#_3-系统安装步骤" aria-label="Permalink to &quot;3.系统安装步骤&quot;">​</a></h3><p>分区：给C盘分配100G以上空间，安装系统到NVMe固态硬盘</p><h3 id="_4-系统装好后必做" tabindex="-1">4.系统装好后必做 <a class="header-anchor" href="#_4-系统装好后必做" aria-label="Permalink to &quot;4.系统装好后必做&quot;">​</a></h3><ol><li>去主板官网下载：芯片组驱动、网卡、声卡驱动（不要用驱动精灵万能公版驱动，容易蓝屏）</li><li>显卡去NVIDIA/AMD官网下载正式版显卡驱动</li></ol><h2 id="五、新机系统设置-优化" tabindex="-1">五、新机系统设置&amp;优化 <a class="header-anchor" href="#五、新机系统设置-优化" aria-label="Permalink to &quot;五、新机系统设置&amp;优化&quot;">​</a></h2><ol><li>分区规划建议 C盘：仅放系统+驱动，150G足够；软件、游戏、资料全部安装到D盘/E盘</li><li>微软商店优化 设置→系统→存储→更改新内容保存位置，将新应用、文档、图片默认路径改到D盘，避免C盘爆满 不需要商店直接组策略禁用，不要强制卸载</li><li>UWP应用管理 系统自带UWP（照片、计算器、Xbox）不要删除，第三方商店APP可以在设置-应用移动到其他磁盘</li><li>关闭多余开机启动项 Ctrl+Shift+Esc打开任务管理器→启动应用，只保留显卡驱动、输入法，其余全部禁用</li></ol><h2 id="六、装机高频避坑指南" tabindex="-1">六、装机高频避坑指南 <a class="header-anchor" href="#六、装机高频避坑指南" aria-label="Permalink to &quot;六、装机高频避坑指南&quot;">​</a></h2><ol><li>电源绝对不能省：杂牌“500W大功率”实际只有300W，烧毁硬件损失上千</li><li>不要盲目追高端CPU：游戏主要看显卡，CPU够用即可，多余预算砸显卡</li><li>固态硬盘别买杂牌高速盘：大概率掉速、掉盘丢失文件</li><li>二手硬件坑：显卡谨慎买矿卡（长期高负载老化，寿命极短）；CPU几乎无损耗，可以二手</li><li>线材不要乱塞机箱：风道堵塞导致高温降频，游戏卡顿</li><li>Windows11刚需：开启BIOS的TPM2.0和Secure Boot，否则无法安装</li></ol><h2 id="七、两种装机方案选择" tabindex="-1">七、两种装机方案选择 <a class="header-anchor" href="#七、两种装机方案选择" aria-label="Permalink to &quot;七、两种装机方案选择&quot;">​</a></h2><ol><li>自己买配件DIY：性价比最高，硬件透明，后期好升级，适合愿意花1小时学习</li><li>品牌整机/笔记本：售后省心，一键保修，无法硬件升级，溢价高，适合纯小白不想折腾</li></ol><h2 id="八、装机完成检查项" tabindex="-1">八、装机完成检查项 <a class="header-anchor" href="#八、装机完成检查项" aria-label="Permalink to &quot;八、装机完成检查项&quot;">​</a></h2><ol><li>用CPU-Z、GPU-Z查看硬件参数，确认没有被改卡造假</li><li>AIDA64单烤FPU测试CPU温度、甜甜圈烤显卡，观察温度是否正常（CPU满载＜85℃、显卡＜80℃为优秀）</li><li>跑3DMark测试显卡稳定性</li><li>测试硬盘CrystalDiskMark，确认固态读写正常</li></ol>',61)])])}const P=l(o,[["render",t]]);export{c as __pageData,P as default};
